/**
 * @name XPath injection
 * @description Constructing XPath expressions from user input can lead to XPath injection attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xpath-injection
 * @tags security
 *        external/cwe/cwe-643
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module XPathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        // lxml xpath() method calls
        call.getFunction().(DataFlow::AttrRead).getAttributeName() = "xpath" or
        // lxml find/findall with xpath
        call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["find", "findall", "findtext"] or
        // XPath constructor
        call = API::moduleImport("lxml").getMember("etree").getMember("XPath").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module XPathInjectionFlow = TaintTracking::Global<XPathInjectionConfig>;
import XPathInjectionFlow::PathGraph

from XPathInjectionFlow::PathNode source, XPathInjectionFlow::PathNode sink
where XPathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XPath expression may be vulnerable to injection from $@.", source.getNode(), "user input"

/**
 * @name SQL injection
 * @description Executing SQL queries with unsanitized user input can lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"

/**
 * @name Open redirect
 * @description URL redirection based on unvalidated user input can lead to phishing attacks
 * @kind path-problem
 * @problem.severity medium
 * @id py/open-redirect
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("webbrowser").getMember("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect from $@.", source.getNode(), "user input"
